const ROOM_CODE_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/** Builds the shareable link that joins a room directly: `<origin>/<roomCode>`. */
export function buildRoomLink(roomCode: string, origin: string): string {
  return `${origin.replace(/\/$/, '')}/${roomCode}`;
}

/**
 * Extracts the room code from a join link path (e.g. `/<room_code>`).
 * Room codes are UUIDs generated by the backend. Returns null when the
 * path does not contain a room code (e.g. the plain home page `/`).
 */
export function getRoomCodeFromUrl(pathname: string): string | null {
  const segment = pathname.replace(/^\/+|\/+$/g, '');
  if (!segment || segment.includes('/')) {
    return null;
  }
  const decoded = decodeURIComponent(segment);
  return ROOM_CODE_PATTERN.test(decoded) ? decoded : null;
}
